#include "stellar/package_manifest.h"
#include "stellar/source.h"
#include <windows.h>
#include <bcrypt.h>
#include <algorithm>
#include <fstream>
#include <iomanip>
#include <set>
#include <sstream>
#include <stdexcept>
#pragma comment(lib, "bcrypt.lib")

namespace stellar::v0_1 {
namespace {
struct JsonValue { enum class Kind{string,array,object} kind; std::string string; std::vector<JsonValue> array; std::map<std::string,JsonValue> object; };
class JsonParser {
 public: explicit JsonParser(const std::string& input):s(input){}
  JsonValue parse(){ws();auto v=value();ws();if(i!=s.size())fail();return v;}
 private:
  const std::string& s; std::size_t i{};
  [[noreturn]] void fail(){throw std::runtime_error("malformed JSON");}
  void ws(){while(i<s.size()&&(s[i]==' '||s[i]=='\n'||s[i]=='\r'||s[i]=='\t'))++i;}
  std::string str(){if(i>=s.size()||s[i++]!='"')fail();std::string r;while(i<s.size()){char c=s[i++];if(c=='"')return r;if(c=='\\'){if(i>=s.size())fail();char e=s[i++];switch(e){case '"':case '\\':case '/':r+=e;break;case 'n':r+='\n';break;case 'r':r+='\r';break;case 't':r+='\t';break;default:fail();}}else{if(static_cast<unsigned char>(c)<0x20)fail();r+=c;}}fail();}
  JsonValue value(){ws();if(i>=s.size())fail();if(s[i]=='"')return{JsonValue::Kind::string,str(),{}, {}};if(s[i]=='['){++i;JsonValue v{JsonValue::Kind::array};ws();if(i<s.size()&&s[i]==']'){++i;return v;}for(;;){v.array.push_back(value());ws();if(i<s.size()&&s[i]==','){++i;continue;}if(i<s.size()&&s[i]==']'){++i;return v;}fail();}}if(s[i]=='{'){++i;JsonValue v{JsonValue::Kind::object};ws();if(i<s.size()&&s[i]=='}'){++i;return v;}for(;;){ws();auto k=str();if(v.object.contains(k))fail();ws();if(i>=s.size()||s[i++]!=':')fail();v.object.emplace(k,value());ws();if(i<s.size()&&s[i]==','){++i;continue;}if(i<s.size()&&s[i]=='}'){++i;return v;}fail();}}fail();}
};
std::string read_all(const std::filesystem::path& p){std::ifstream in(p,std::ios::binary);if(!in)throw std::runtime_error("read");return{std::istreambuf_iterator<char>(in),{}};}
const JsonValue& field(const JsonValue& root,const std::string& key,JsonValue::Kind kind){auto it=root.object.find(key);if(it==root.object.end()||it->second.kind!=kind)throw std::runtime_error("field");return it->second;}
std::vector<std::string> strings(const JsonValue& root,const std::string& key){std::vector<std::string> out;for(const auto& v:field(root,key,JsonValue::Kind::array).array){if(v.kind!=JsonValue::Kind::string)throw std::runtime_error("array");out.push_back(v.string);}return out;}
std::string array_json(const std::vector<std::string>& values){std::ostringstream o;o<<'[';for(std::size_t i=0;i<values.size();++i){if(i)o<<',';o<<'"'<<json_escape(values[i])<<'"';}return o.str()+']';}
std::string canonical(const PackageManifest& m){std::ostringstream o;o<<"{\"capabilities\":"<<array_json(m.capabilities)<<",\"entry\":\""<<json_escape(m.entry)<<"\",\"modules\":"<<array_json(m.modules)<<",\"name\":\""<<json_escape(m.name)<<"\",\"profile\":\""<<json_escape(m.profile)<<"\",\"relics\":"<<array_json(m.relics)<<",\"schema\":\""<<json_escape(m.schema)<<"\",\"target\":\""<<json_escape(m.target)<<"\",\"version\":\""<<json_escape(m.version)<<"\"}";return o.str();}
bool confined(const std::filesystem::path& root,const std::string& relative,std::filesystem::path& resolved){std::filesystem::path r(relative);if(r.empty()||r.is_absolute())return false;for(const auto& part:r)if(part=="..")return false;std::error_code ec;resolved=std::filesystem::weakly_canonical(root/r,ec);if(ec)return false;auto base=std::filesystem::weakly_canonical(root,ec);if(ec)return false;auto b=base.native(),x=resolved.native();std::transform(b.begin(),b.end(),b.begin(),::towlower);std::transform(x.begin(),x.end(),x.begin(),::towlower);return x.size()>b.size()&&x.compare(0,b.size(),b)==0&&(x[b.size()]=='\\'||x[b.size()]=='/');}
}

std::string sha256_text(const std::string& text){BCRYPT_ALG_HANDLE alg{};BCRYPT_HASH_HANDLE hash{};DWORD object_size{},bytes{};std::vector<unsigned char> object,output(32);if(BCryptOpenAlgorithmProvider(&alg,BCRYPT_SHA256_ALGORITHM,nullptr,0)<0)throw std::runtime_error("sha256");if(BCryptGetProperty(alg,BCRYPT_OBJECT_LENGTH,reinterpret_cast<PUCHAR>(&object_size),sizeof(object_size),&bytes,0)<0){BCryptCloseAlgorithmProvider(alg,0);throw std::runtime_error("sha256");}object.resize(object_size);if(BCryptCreateHash(alg,&hash,object.data(),object_size,nullptr,0,0)<0||BCryptHashData(hash,reinterpret_cast<PUCHAR>(const_cast<char*>(text.data())),static_cast<ULONG>(text.size()),0)<0||BCryptFinishHash(hash,output.data(),static_cast<ULONG>(output.size()),0)<0){if(hash)BCryptDestroyHash(hash);BCryptCloseAlgorithmProvider(alg,0);throw std::runtime_error("sha256");}BCryptDestroyHash(hash);BCryptCloseAlgorithmProvider(alg,0);std::ostringstream o;o<<"sha256:"<<std::hex<<std::setfill('0');for(auto b:output)o<<std::setw(2)<<static_cast<int>(b);return o.str();}

bool inspect_manifest(const std::filesystem::path& path,PackageInspection& result,Diagnostic& error){const auto display=std::filesystem::absolute(path).generic_string();try{const auto text=read_all(path);if(text.size()>65536)throw std::runtime_error("size");auto root=JsonParser(text).parse();if(root.kind!=JsonValue::Kind::object)throw std::runtime_error("object");const std::set<std::string> allowed{"schema","name","version","target","profile","entry","modules","relics","capabilities"};for(const auto& [k,v]:root.object)if(!allowed.contains(k))throw std::runtime_error("unknown");PackageManifest m{field(root,"schema",JsonValue::Kind::string).string,field(root,"name",JsonValue::Kind::string).string,field(root,"version",JsonValue::Kind::string).string,field(root,"target",JsonValue::Kind::string).string,field(root,"profile",JsonValue::Kind::string).string,field(root,"entry",JsonValue::Kind::string).string,strings(root,"modules"),strings(root,"relics"),strings(root,"capabilities")};if(m.schema!="stellar.package/v0.1"||m.target!="windows-x86_64-msvc"||m.profile!="stellar-lab-v0"||m.modules.empty()||m.modules.size()>128)throw std::runtime_error("contract");std::set<std::string> unique;const auto package_root=std::filesystem::absolute(path).parent_path();auto inspect_path=[&](const std::string& rel){std::filesystem::path resolved;if(!confined(package_root,rel,resolved)){error={"S5002","error","package path escapes its package root",display,{},"use a normalized relative path contained by the package directory"};return false;}if(!std::filesystem::is_regular_file(resolved)){error={"S5001","error","package module is unavailable",display,{},"declare an existing regular source module"};return false;}return true;};if(!inspect_path(m.entry))return false;for(const auto& module:m.modules){if(!unique.insert(module).second)throw std::runtime_error("duplicate");std::filesystem::path resolved;if(!confined(package_root,module,resolved)){error={"S5002","error","package path escapes its package root",display,{},"use a normalized relative path contained by the package directory"};return false;}if(!std::filesystem::is_regular_file(resolved)){error={"S5001","error","package module is unavailable",display,{},"declare an existing regular source module"};return false;}result.module_hashes[module]=sha256_text(read_all(resolved));}if(!unique.contains(m.entry))throw std::runtime_error("entry");result.canonical_manifest=canonical(m);result.integrity=sha256_text(result.canonical_manifest);return true;}catch(...){if(error.code.empty())error={"S5001","error","manifest violates the stellar.package/v0.1 schema",display,{},"use the closed v0.1 schema with unique relative module paths"};return false;}}

std::string inspection_json(const PackageInspection& r){std::ostringstream o;o<<"{\"canonicalManifest\":"<<r.canonical_manifest<<",\"integrity\":\""<<r.integrity<<"\",\"moduleHashes\":{";bool first=true;for(const auto&[k,v]:r.module_hashes){if(!first)o<<',';first=false;o<<'"'<<json_escape(k)<<"\":\""<<v<<'"';}o<<"}}";return o.str();}
bool write_lock(const std::filesystem::path& manifest,const PackageInspection& r,Diagnostic& error){try{const auto target=manifest.parent_path()/"stellar.lock.json";std::ofstream o(target,std::ios::binary|std::ios::trunc);if(!o)throw std::runtime_error("write");o<<"{\"moduleHashes\":{";bool first=true;for(const auto&[k,v]:r.module_hashes){if(!first)o<<',';first=false;o<<'"'<<json_escape(k)<<"\":\""<<v<<'"';}o<<"},\"packageIntegrity\":\""<<r.integrity<<"\",\"schema\":\"stellar.lock/v0.1\"}\n";return true;}catch(...){error={"S5004","error","lock file could not be written",std::filesystem::absolute(manifest).generic_string(),{},"ensure the package directory is writable"};return false;}}
bool verify_lock(const std::filesystem::path& manifest,const PackageInspection& r,Diagnostic& error){try{auto root=JsonParser(read_all(manifest.parent_path()/"stellar.lock.json")).parse();const std::set<std::string> allowed{"schema","packageIntegrity","moduleHashes"};if(root.kind!=JsonValue::Kind::object||root.object.size()!=allowed.size())throw std::runtime_error("schema");for(const auto&[key,value]:root.object)if(!allowed.contains(key))throw std::runtime_error("unknown");if(field(root,"schema",JsonValue::Kind::string).string!="stellar.lock/v0.1"||field(root,"packageIntegrity",JsonValue::Kind::string).string!=r.integrity)throw std::runtime_error("integrity");const auto& hashes=field(root,"moduleHashes",JsonValue::Kind::object).object;if(hashes.size()!=r.module_hashes.size())throw std::runtime_error("hashes");for(const auto&[k,v]:r.module_hashes){auto it=hashes.find(k);if(it==hashes.end()||it->second.kind!=JsonValue::Kind::string||it->second.string!=v)throw std::runtime_error("hash");}return true;}catch(...){error={"S5003","error","package or module integrity does not match stellar.lock.json",std::filesystem::absolute(manifest).generic_string(),{},"restore reviewed bytes or issue a new reviewed lock; checksum integrity is not authorization"};return false;}}
}
